window.__votdWeek && window.__votdWeek({"week":"2029-08-13","reading":"Doctrine and Covenants 88","days":[{"d":"2029-08-13","ref":"D&C 88:13","b":"D&C","c":88,"v":13,"he":"הָאוֹר אֲשֶׁר בַּכֹּל הַנּוֹתֵן חַיִּים לַכֹּל אֲשֶׁר הוּא הַתּוֹרָה אֲשֶׁר בָּהּ נִמְשָׁל הַכֹּל גַּם כֹּחַ אֱלֹהִים הַיּוֹשֵׁב עַל כִּסְאוֹ אֲשֶׁר הוּא בְּחֵיק הַנֶּצַח אֲשֶׁר הוּא בְּתוֹךְ הַכֹּל׃","en":"The light which is in all things, which giveth life to all things, which is the law by which all things are governed, even the power of God who sitteth upon his throne, who is in the bosom of eternity, who is in the midst of all things."},{"d":"2029-08-14","ref":"D&C 88:47","b":"D&C","c":88,"v":47,"he":"הִנֵּה כׇּל אֵלֶּה מַמְלָכוֹת הֵם וְכׇל אָדָם אֲשֶׁר רָאָה אַחַת אוֹ אֶת־הַקְּטַנָּה אֲשֶׁר בָּהֶם רָאָה אֶת־אֱלֹהִים נָע בְּהוֹדוֹ וּבְכֹחוֹ׃","en":"Behold, all these are kingdoms, and any man who hath seen any or the least of these hath seen God moving in his majesty and power."},{"d":"2029-08-15","ref":"D&C 88:63","b":"D&C","c":88,"v":63,"he":"קִרְבוּ אֵלַי וַאֲנִי אֶקְרַב אֲלֵיכֶם דִּרְשׁוּנִי הֵיטֵב וְתִמְצְאוּנִי שַׁאֲלוּ וּתְקַבְּלוּ דִּפְקוּ וְיִפָּתַח לָכֶם׃","en":"Draw near unto me and I will draw near unto you; seek me diligently and ye shall find me; ask, and ye shall receive; knock, and it shall be opened unto you."},{"d":"2029-08-16","ref":"D&C 88:67","b":"D&C","c":88,"v":67,"he":"וְאִם עֵינְכֶם תְּמִימָה לִכְבוֹדִי כׇּל גּוּפְכֶם יִמָּלֵא אוֹר וְלֹא יִהְיֶה חֹשֶׁךְ בָּכֶם וְהַגּוּף הַמָּלֵא אוֹר מֵבִין אֶת־הַכֹּל׃","en":"And if your eye be single to my glory, your whole bodies shall be filled with light, and there shall be no darkness in you; and that body which is filled with light comprehendeth all things."},{"d":"2029-08-17","ref":"D&C 88:68","b":"D&C","c":88,"v":68,"he":"לָכֵן הִתְקַדְּשׁוּ לְמַעַן מַחְשְׁבוֹתֵיכֶם תִּהְיֶינָה תְּמִימוֹת לֵאלֹהִים וְיָבֹאוּ הַיָּמִים אֲשֶׁר תִּרְאוּ אוֹתוֹ כִּי יְגַלֶּה אֶת־פָּנָיו לָכֶם וְיִהְיֶה בְּעִתּוֹ וּבְדַרְכּוֹ וּכְפִי רְצוֹנוֹ׃","en":"Therefore, sanctify yourselves that your minds become single to God, and the days will come that you shall see him; for he will unveil his face unto you, and it shall be in his own time, and in his own way, and according to his own will."},{"d":"2029-08-18","ref":"D&C 88:86","b":"D&C","c":88,"v":86,"he":"עִמְדוּ בַּחֵרוּת אֲשֶׁר בָּהּ נַעֲשֵׂיתֶם חׇפְשִׁיִּים אַל תִּלָּכְדוּ בַּחֵטְא כִּי־אִם תִּהְיֶינָה יְדֵיכֶם נְקִיּוֹת עַד בּוֹא יְהוָה׃","en":"Abide ye in the liberty wherewith ye are made free; entangle not yourselves in sin, but let your hands be clean, until the Lord comes."},{"d":"2029-08-19","ref":"D&C 88:118","b":"D&C","c":88,"v":118,"he":"וְכַאֲשֶׁר אֵין לַכֹּל אֱמוּנָה בַּקְּשׁוּ הֵיטֵב וְלַמְּדוּ זֶה אֶת־זֶה דִּבְרֵי חׇכְמָה אָכֵן בַּקְּשׁוּ מִתּוֹךְ הַסְּפָרִים הַטּוֹבִים דִּבְרֵי חׇכְמָה בַּקְּשׁוּ דַעַת גַּם בְּלִמּוּד וְגַם בֶּאֱמוּנָה׃","en":"And as all have not faith, seek ye diligently and teach one another words of wisdom; yea, seek ye out of the best books words of wisdom; seek learning, even by study and also by faith."}]});
